    (void)r58_movie_set_title(&mv, "A_CAM_SLATE_37CHARS_MAX_VALID_STRING1");
    st.file_number_series = 0; /* Reset */
    (void)r58_still_set_prefix(&st, "FX3");
    st.folder_form = R58_FOLDER_DATE;
