    (void)rmdir("/mnt/r58c_surfaces");
    (void)rmdir("/mnt/r58c_p2_ro");
    (void)rmdir("/mnt/r58c_cnflasha_ro");

    clock_gettime(CLOCK_MONOTONIC, &t1);
