    errno = 0;
    int ro_fd = open("/mnt/r59_p2_init/Backup.bin", O_RDWR);
    int p2_write_blocked_rc = (ro_fd >= 0) ? (close(ro_fd), 0) : -errno;
    errno = 0;
    int v_fd = open("/mnt/r59_slot1_vault/BODYDATA.DAT", O_RDWR);
