    /* Guard 1: Dormant Lossless Comp L/M/S, FX6 still-less, and HLG Still prerequisite lockouts */
    int lossless_base_rc = r63_set_raw_file_type(&cfg, R63_RAW_LOSSLESS_DORMANT);
